/**
 * What a prerendered page says about itself, read from its HTML.
 *
 * Pure: it receives HTML text and returns facts, so the rules in `checks.ts` are
 * tested on small fixtures and the command-line wrapper only walks the build folder.
 * The HTML is machine-generated by React with double-quoted attributes, which a
 * tolerant regex reader handles; this is not a general-purpose HTML parser.
 */

export type Anchor = {
  href: string;
  rel: string;
  text: string;
  /** For a sponsored link: an affiliate disclosure appears within a short distance of it. Always true for other links. */
  disclosureNearby: boolean;
};

export type PageFacts = {
  path: string;
  title: string | null;
  description: string | null;
  canonical: string | null;
  robots: string | null;
  og: Record<string, string>;
  twitter: Record<string, string>;
  jsonLd: { types: string[]; invalid: number };
  h1Count: number;
  /** "v0.12.0 · 354 tools across 27 categories · sources last verified October 8, 2026", whitespace-normalised. */
  footerLine: string | null;
  anchors: Anchor[];
  /** Visible text: scripts, styles and tags removed, entities decoded, whitespace collapsed. */
  text: string;
};

const ENTITIES: Record<string, string> = { "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#x27;": "'", "&#39;": "'", "&nbsp;": " " };

export function decodeEntities(text: string): string {
  return text
    .replace(/&(?:amp|lt|gt|quot|nbsp|#x27|#39);/g, (match) => ENTITIES[match] ?? match)
    .replace(/&#x([0-9a-f]+);/gi, (_, hex: string) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, decimal: string) => String.fromCodePoint(Number(decimal)));
}

function parseAttributes(raw: string): Record<string, string> {
  const attributes: Record<string, string> = {};
  for (const match of raw.matchAll(/([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g)) {
    attributes[match[1]!.toLowerCase()] = decodeEntities(match[2] ?? match[3] ?? match[4] ?? "");
  }
  return attributes;
}

export function stripTags(html: string): string {
  return decodeEntities(html.replace(/<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>|<!--[\s\S]*?-->|<[^>]*>/gi, " ")).replace(/\s+/g, " ").trim();
}

const FOOTER_LINE = /v\s*[\d.]+\s*·\s*\d+\s*tools across\s*\d+\s*categories\s*·\s*sources last verified\s*[A-Za-z]+\s*\d{1,2},\s*\d{4}/;

function collectTypes(value: unknown, into: string[]): void {
  if (Array.isArray(value)) {
    for (const item of value) collectTypes(item, into);
  } else if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    const type = record["@type"];
    if (typeof type === "string") into.push(type);
    else if (Array.isArray(type)) into.push(...type.filter((t): t is string => typeof t === "string"));
    for (const child of Object.values(record)) collectTypes(child, into);
  }
}

/** How far around a sponsored link a disclosure may sit and still count as "next to it". */
const DISCLOSURE_AFTER_CHARS = 700;
const DISCLOSURE_BEFORE_CHARS = 300;

export function parsePageFacts(path: string, html: string): PageFacts {
  const og: Record<string, string> = {};
  const twitter: Record<string, string> = {};
  let description: string | null = null;
  let robots: string | null = null;
  let canonical: string | null = null;

  for (const match of html.matchAll(/<(meta|link)\b([^>]*)>/gi)) {
    const attributes = parseAttributes(match[2]!);
    if (match[1]!.toLowerCase() === "link") {
      if (attributes["rel"]?.split(/\s+/).includes("canonical") && attributes["href"]) canonical = attributes["href"];
      continue;
    }
    const key = attributes["property"] ?? attributes["name"];
    const content = attributes["content"];
    if (!key || content === undefined) continue;
    if (key.startsWith("og:")) og[key.slice(3)] ??= content;
    else if (key.startsWith("twitter:")) twitter[key.slice(8)] ??= content;
    else if (key === "description") description ??= content;
    else if (key === "robots") robots = robots === null ? content : `${robots}, ${content}`; // crawlers apply the strictest of several robots tags
  }

  const titleMatch = /<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(html);

  const types: string[] = [];
  let invalid = 0;
  for (const match of html.matchAll(/<script\b[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      collectTypes(JSON.parse(match[1]!), types);
    } catch {
      invalid += 1;
    }
  }

  const anchors: Anchor[] = [];
  for (const match of html.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)) {
    const attributes = parseAttributes(match[1]!);
    if (!attributes["href"]) continue;
    const rel = attributes["rel"] ?? "";
    let disclosureNearby = true;
    if (rel.split(/\s+/).includes("sponsored")) {
      const end = match.index! + match[0].length;
      const after = stripTags(html.slice(end, end + 1500)).slice(0, DISCLOSURE_AFTER_CHARS);
      const before = stripTags(html.slice(Math.max(0, match.index! - 600), match.index!)).slice(-DISCLOSURE_BEFORE_CHARS);
      disclosureNearby = /affiliate/i.test(after) || /affiliate/i.test(before);
    }
    anchors.push({ href: attributes["href"], rel, text: stripTags(match[2]!), disclosureNearby });
  }

  const footers = [...html.matchAll(/<footer\b[\s\S]*?<\/footer>/gi)];
  const footerText = footers.length > 0 ? stripTags(footers[footers.length - 1]![0]) : "";
  const footerMatch = FOOTER_LINE.exec(footerText);

  return {
    path,
    title: titleMatch ? decodeEntities(titleMatch[1]!.replace(/\s+/g, " ").trim()) : null,
    description,
    canonical,
    robots,
    og,
    twitter,
    jsonLd: { types: [...new Set(types)].sort(), invalid },
    h1Count: [...html.matchAll(/<h1\b/gi)].length,
    footerLine: footerMatch ? footerMatch[0].replace(/\s+/g, " ").replace(/^v /, "v") : null,
    anchors,
    text: stripTags(html),
  };
}

/** The page's own `robots` directive forbids indexing. */
export function isNoindex(page: Pick<PageFacts, "robots">): boolean {
  return /(^|[\s,])(noindex|none)([\s,]|$)/i.test(page.robots ?? "");
}
